//! Planet layers, real proportions, and the settings a world-creation screen
//! would collect.
//!
//! Real Earth, by radius (6,371 km): inner core 0–1,220 km, outer core
//! 1,220–3,480 km, mantle 3,480–6,351 km, crust 6,351–6,371 km. That is the
//! default here. A profile stores **fractions of the surface radius**, so a
//! planet of any diameter keeps the same proportions unless the player changes
//! them.
//!
//! A solid planet cannot be generated by walking a column: it is millions of
//! blocks deep. The profile is used only to classify a radius. Generation stays
//! a bounded band around the surface or the player; see `Column` in
//! `planet.rs` and `LocalWindow` in `stream.rs`.

use crate::planet::Block;

pub const KM_IN_BLOCKS: f64 = 1000.0;
pub const EARTH_DIAMETER_KM: f64 = 12_742.0;
/// Slider ends are chosen so Earth sits at the geometric centre:
/// `sqrt(1,000 * 162,000) ~= 12,728 km`.
pub const MIN_DIAMETER_KM: f64 = 1_000.0;
pub const MAX_DIAMETER_KM: f64 = 162_000.0;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PlanetKind {
    EarthLike,
    MarsLike,
    MoonLike,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LayerId {
    Crust,
    Mantle,
    OuterCore,
    InnerCore,
    Core,
}

impl LayerId {
    pub fn label(self) -> &'static str {
        match self {
            LayerId::Crust => "Crust",
            LayerId::Mantle => "Mantle",
            LayerId::OuterCore => "Outer core",
            LayerId::InnerCore => "Inner core",
            LayerId::Core => "Core",
        }
    }
}

impl PlanetKind {
    pub fn label(self) -> &'static str {
        match self {
            PlanetKind::EarthLike => "Earth-like",
            PlanetKind::MarsLike => "Mars-like",
            PlanetKind::MoonLike => "Moon-like",
        }
    }

    pub fn default_diameter_km(self) -> f64 {
        match self {
            PlanetKind::EarthLike => EARTH_DIAMETER_KM,
            PlanetKind::MarsLike => 6_780.0,
            PlanetKind::MoonLike => 3_474.0,
        }
    }

    /// Outer-to-inner layers.
    pub fn layer_ids(self) -> &'static [LayerId] {
        match self {
            PlanetKind::EarthLike => &[
                LayerId::Crust,
                LayerId::Mantle,
                LayerId::OuterCore,
                LayerId::InnerCore,
            ],
            PlanetKind::MarsLike => &[LayerId::Crust, LayerId::Mantle, LayerId::Core],
            PlanetKind::MoonLike => &[LayerId::Crust, LayerId::Mantle, LayerId::Core],
        }
    }

    /// Default thicknesses in km, matching the real body (Earth's are the
    /// standard model values).
    pub fn default_thickness_km(self) -> &'static [f64] {
        match self {
            // 20 km average crust, 2,871 mantle, 2,260 outer core, 1,220
            // inner core. Sum 6,371.
            PlanetKind::EarthLike => &[20.0, 2_871.0, 2_260.0, 1_220.0],
            // Mars: 50 km crust, 1,510 mantle, 1,830 core. Sum 3,390.
            PlanetKind::MarsLike => &[50.0, 1_510.0, 1_830.0],
            // Moon: 40 km crust, 1,457 mantle, 240 core. Sum 1,737.
            PlanetKind::MoonLike => &[40.0, 1_457.0, 240.0],
        }
    }

    /// Slider ranges in km for the advanced layer settings, one per layer.
    /// At other diameters the same *fraction* range applies and the editor
    /// shows the km value for the chosen diameter.
    pub fn slider_ranges_km(self) -> &'static [(f64, f64)] {
        match self {
            PlanetKind::EarthLike => &[
                (5.0, 70.0),
                (500.0, 4_000.0),
                (500.0, 3_000.0),
                (100.0, 2_000.0),
            ],
            PlanetKind::MarsLike => &[(10.0, 100.0), (500.0, 3_500.0), (500.0, 2_500.0)],
            PlanetKind::MoonLike => &[(5.0, 100.0), (500.0, 2_300.0), (50.0, 800.0)],
        }
    }

    pub fn surface_block(self) -> Block {
        match self {
            PlanetKind::EarthLike => Block::Grass,
            PlanetKind::MarsLike => Block::Dirt,
            PlanetKind::MoonLike => Block::Stone,
        }
    }

    pub fn subsurface_block(self) -> Block {
        match self {
            PlanetKind::EarthLike => Block::Dirt,
            PlanetKind::MarsLike => Block::Dirt,
            PlanetKind::MoonLike => Block::Stone,
        }
    }

    pub fn has_ocean(self) -> bool {
        matches!(self, PlanetKind::EarthLike)
    }

    fn layer_block(self, id: LayerId) -> Block {
        match (self, id) {
            (_, LayerId::Crust) => Block::Stone,
            (PlanetKind::EarthLike, LayerId::Mantle) => Block::Deepslate,
            (PlanetKind::EarthLike, LayerId::OuterCore) => Block::Lava,
            (PlanetKind::EarthLike, LayerId::InnerCore) => Block::Bedrock,
            (PlanetKind::MarsLike, LayerId::Mantle) => Block::Deepslate,
            (PlanetKind::MarsLike, LayerId::Core) => Block::Lava,
            (PlanetKind::MoonLike, LayerId::Mantle) => Block::Deepslate,
            (PlanetKind::MoonLike, LayerId::Core) => Block::Bedrock,
            _ => Block::Deepslate,
        }
    }
}

/// One layer, as fractions of the surface radius. `outer` of the first layer is
/// 1.0; `inner` of the last is 0.0.
#[derive(Clone, Copy, Debug)]
pub struct Layer {
    pub id: LayerId,
    pub block: Block,
    pub inner: f64,
    pub outer: f64,
}

impl Layer {
    pub fn name(&self) -> &'static str {
        self.id.label()
    }

    pub fn thickness_fraction(&self) -> f64 {
        (self.outer - self.inner).max(0.0)
    }

    /// Share of the planet's volume: `outer³ − inner³`.
    pub fn volume_share(&self) -> f64 {
        self.outer.powi(3) - self.inner.powi(3)
    }

    pub fn thickness_km(&self, radius_km: f64) -> f64 {
        self.thickness_fraction() * radius_km
    }
}

#[derive(Clone, Debug)]
pub struct LayerProfile {
    pub kind: PlanetKind,
    /// Outer to inner.
    pub layers: Vec<Layer>,
}

impl LayerProfile {
    pub fn for_kind(kind: PlanetKind) -> Self {
        let fractions = default_fractions(kind);
        Self::from_fractions(kind, &fractions).expect("default layers are valid")
    }

    /// Build a profile from positive thickness fractions; they are normalized
    /// to sum to 1, so a slider cannot create a gap or an overlap.
    pub fn from_fractions(kind: PlanetKind, fractions: &[f64]) -> Result<Self, SettingsError> {
        if fractions.len() != kind.layer_ids().len() {
            return Err(SettingsError::LayerCount);
        }
        if fractions.iter().any(|f| !f.is_finite() || *f <= 0.0) {
            return Err(SettingsError::NonPositiveLayer);
        }
        let sum: f64 = fractions.iter().sum();
        if sum <= 0.0 {
            return Err(SettingsError::NonPositiveLayer);
        }

        let mut layers = Vec::with_capacity(fractions.len());
        let mut outer = 1.0;
        for (id, fraction) in kind.layer_ids().iter().zip(fractions) {
            let thickness = fraction / sum;
            let inner = (outer - thickness).max(0.0);
            layers.push(Layer {
                id: *id,
                block: kind.layer_block(*id),
                inner,
                outer,
            });
            outer = inner;
        }
        // Absorb floating-point drift in the innermost layer.
        if let Some(last) = layers.last_mut() {
            last.inner = 0.0;
        }

        Ok(Self { kind, layers })
    }

    pub fn layer_at(&self, fraction: f64) -> &Layer {
        let f = fraction.clamp(0.0, 1.0);
        self.layers
            .iter()
            .find(|l| f >= l.inner && f <= l.outer)
            .unwrap_or_else(|| self.layers.last().expect("profile has layers"))
    }

    pub fn block_at(&self, fraction: f64) -> Block {
        self.layer_at(fraction).block
    }

    pub fn surface_block(&self) -> Block {
        self.kind.surface_block()
    }

    pub fn subsurface_block(&self) -> Block {
        self.kind.subsurface_block()
    }

    pub fn has_ocean(&self) -> bool {
        self.kind.has_ocean()
    }

    pub fn validate(&self) -> bool {
        if self.layers.is_empty() {
            return false;
        }
        let first = self.layers.first().unwrap();
        let last = self.layers.last().unwrap();
        if (first.outer - 1.0).abs() > 1e-9 || last.inner.abs() > 1e-9 {
            return false;
        }
        let contiguous = self
            .layers
            .windows(2)
            .all(|w| (w[0].inner - w[1].outer).abs() < 1e-9);
        let sum: f64 = self.layers.iter().map(|l| l.thickness_fraction()).sum();
        contiguous && (sum - 1.0).abs() < 1e-9
    }
}

fn default_fractions(kind: PlanetKind) -> Vec<f64> {
    let thicknesses = kind.default_thickness_km();
    let sum: f64 = thicknesses.iter().sum();
    thicknesses.iter().map(|t| t / sum).collect()
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SettingsError {
    BadDiameter,
    LayerCount,
    NonPositiveLayer,
    BadFormat,
}

/// The settings a "Create world" screen collects, in the order it collects
/// them: planet type, diameter, then (optionally) one thickness per layer.
#[derive(Clone, Debug, PartialEq)]
pub struct PlanetSettings {
    pub kind: PlanetKind,
    pub diameter_km: f64,
    pub advanced_layers: bool,
    /// Thickness fractions, outer to inner. Ignored unless `advanced_layers`.
    pub layer_fractions: Vec<f64>,
    pub seed: u64,
}

impl PlanetSettings {
    pub fn default_for(kind: PlanetKind) -> Self {
        Self {
            kind,
            diameter_km: kind.default_diameter_km(),
            advanced_layers: false,
            layer_fractions: default_fractions(kind),
            seed: 1,
        }
    }

    pub fn earth_default() -> Self {
        Self::default_for(PlanetKind::EarthLike)
    }

    pub fn radius_km(&self) -> f64 {
        self.diameter_km / 2.0
    }

    pub fn diameter_blocks(&self) -> u64 {
        (self.diameter_km * KM_IN_BLOCKS).round().max(64.0) as u64
    }

    /// Layer thicknesses in km at the chosen diameter, for the editor labels.
    pub fn layer_km(&self) -> Vec<f64> {
        let fractions = if self.advanced_layers {
            &self.layer_fractions
        } else {
            &default_fractions(self.kind)
        };
        let sum: f64 = fractions.iter().sum();
        if sum <= 0.0 {
            return vec![0.0; fractions.len()];
        }
        fractions
            .iter()
            .map(|f| f / sum * self.radius_km())
            .collect()
    }

    pub fn validate(&self) -> Result<(), SettingsError> {
        if !(MIN_DIAMETER_KM..=MAX_DIAMETER_KM).contains(&self.diameter_km) {
            return Err(SettingsError::BadDiameter);
        }
        let fractions = if self.advanced_layers {
            &self.layer_fractions
        } else {
            &default_fractions(self.kind)
        };
        if fractions.len() != self.kind.layer_ids().len() {
            return Err(SettingsError::LayerCount);
        }
        if fractions.iter().any(|f| !f.is_finite() || *f <= 0.0) {
            return Err(SettingsError::NonPositiveLayer);
        }
        Ok(())
    }

    pub fn profile(&self) -> Result<LayerProfile, SettingsError> {
        self.validate()?;
        let fractions = if self.advanced_layers {
            self.layer_fractions.clone()
        } else {
            default_fractions(self.kind)
        };
        LayerProfile::from_fractions(self.kind, &fractions)
    }

    /// Position of the diameter on the logarithmic Create World slider.
    pub fn diameter_slider(&self) -> f32 {
        let lo = MIN_DIAMETER_KM.ln();
        let hi = MAX_DIAMETER_KM.ln();
        (((self
            .diameter_km
            .clamp(MIN_DIAMETER_KM, MAX_DIAMETER_KM)
            .ln()
            - lo)
            / (hi - lo))
            .clamp(0.0, 1.0)) as f32
    }

    pub fn set_diameter_slider(&mut self, position: f32) {
        let t = f64::from(position.clamp(0.0, 1.0));
        let lo = MIN_DIAMETER_KM.ln();
        let hi = MAX_DIAMETER_KM.ln();
        self.diameter_km = (lo + t * (hi - lo)).exp();
    }

    pub fn select_kind(&mut self, kind: PlanetKind) {
        self.kind = kind;
        self.diameter_km = kind.default_diameter_km();
        self.advanced_layers = false;
        self.layer_fractions = default_fractions(kind);
    }

    /// Reset the advanced sliders to the selected body's real layers.
    pub fn reset_layers(&mut self) {
        self.advanced_layers = false;
        self.layer_fractions = default_fractions(self.kind);
    }

    /// Slider position for layer `index`, from its thickness in km. The
    /// slider ranges are the real body's ranges from the Create World design.
    pub fn layer_slider(&self, index: usize) -> f32 {
        let Some(&(min, max)) = self.kind.slider_ranges_km().get(index) else {
            return 0.0;
        };
        let km = self.layer_km().get(index).copied().unwrap_or(min);
        (((km - min) / (max - min).max(1e-9)).clamp(0.0, 1.0)) as f32
    }

    /// Set one advanced layer from its slider position, then normalize all
    /// fractions so the layers still meet without a gap or an overlap.
    pub fn set_layer_slider(&mut self, index: usize, position: f32) {
        let Some(&(min, max)) = self.kind.slider_ranges_km().get(index) else {
            return;
        };
        if !self.advanced_layers {
            self.layer_fractions = default_fractions(self.kind);
            self.advanced_layers = true;
        }
        if self.layer_fractions.len() != self.kind.layer_ids().len() {
            self.layer_fractions = default_fractions(self.kind);
        }
        let km = min + f64::from(position.clamp(0.0, 1.0)) * (max - min);
        self.layer_fractions[index] = (km / self.radius_km().max(1.0)).max(1e-6);
        normalize(&mut self.layer_fractions);
    }

    /// Stable, human-readable persistence format. It is line based so the
    /// native bundle needs no serialization dependency; every value is
    /// validated again on load.
    pub fn encode(&self) -> String {
        let mut out = format!(
            "version = 1\nkind = {}\ndiameter_km = {:.6}\nadvanced_layers = {}\nseed = {}\nlayer_count = {}\n",
            kind_key(self.kind),
            self.diameter_km,
            self.advanced_layers,
            self.seed,
            self.layer_fractions.len()
        );
        for (i, fraction) in self.layer_fractions.iter().enumerate() {
            out.push_str(&format!("layer_{i} = {fraction:.12}\n"));
        }
        out
    }

    pub fn decode(text: &str) -> Result<Self, SettingsError> {
        let mut kind = None;
        let mut diameter_km = None;
        let mut advanced_layers = false;
        let mut seed = 1u64;
        let mut fractions = Vec::new();
        for line in text.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let Some((key, value)) = line.split_once('=') else {
                return Err(SettingsError::BadFormat);
            };
            let key = key.trim();
            let value = value.trim();
            match key {
                "version" => {
                    if value != "1" {
                        return Err(SettingsError::BadFormat);
                    }
                }
                "kind" => kind = Some(parse_kind(value)?),
                "diameter_km" => {
                    diameter_km = Some(value.parse().map_err(|_| SettingsError::BadFormat)?)
                }
                "advanced_layers" => {
                    advanced_layers = value.parse().map_err(|_| SettingsError::BadFormat)?
                }
                "seed" => seed = value.parse().map_err(|_| SettingsError::BadFormat)?,
                "layer_count" => {
                    let _: usize = value.parse().map_err(|_| SettingsError::BadFormat)?;
                }
                key if key.starts_with("layer_") => {
                    let index: usize = key[6..].parse().map_err(|_| SettingsError::BadFormat)?;
                    if index != fractions.len() {
                        return Err(SettingsError::BadFormat);
                    }
                    fractions.push(value.parse().map_err(|_| SettingsError::BadFormat)?);
                }
                _ => return Err(SettingsError::BadFormat),
            }
        }
        let kind = kind.ok_or(SettingsError::BadFormat)?;
        let settings = Self {
            kind,
            diameter_km: diameter_km.ok_or(SettingsError::BadFormat)?,
            advanced_layers,
            layer_fractions: fractions,
            seed,
        };
        settings.validate()?;
        if settings.layer_fractions.len() != kind.layer_ids().len() {
            return Err(SettingsError::LayerCount);
        }
        Ok(settings)
    }
}

fn kind_key(kind: PlanetKind) -> &'static str {
    match kind {
        PlanetKind::EarthLike => "earth",
        PlanetKind::MarsLike => "mars",
        PlanetKind::MoonLike => "moon",
    }
}

fn parse_kind(value: &str) -> Result<PlanetKind, SettingsError> {
    match value {
        "earth" => Ok(PlanetKind::EarthLike),
        "mars" => Ok(PlanetKind::MarsLike),
        "moon" => Ok(PlanetKind::MoonLike),
        _ => Err(SettingsError::BadFormat),
    }
}

fn normalize(fractions: &mut [f64]) {
    let sum: f64 = fractions.iter().filter(|f| f.is_finite()).sum();
    if sum <= 0.0 {
        return;
    }
    for fraction in fractions {
        *fraction = (*fraction).max(0.0) / sum;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn earth_layers_match_the_real_proportions() {
        let profile = LayerProfile::for_kind(PlanetKind::EarthLike);
        assert_eq!(profile.layers.len(), 4);
        assert!(profile.validate());

        let shares: Vec<f64> = profile.layers.iter().map(|l| l.volume_share()).collect();
        // Crust ~1% of volume, mantle ~83%, outer core ~15.6%, inner core ~0.7%.
        assert!((0.5..1.5).contains(&(shares[0] * 100.0)), "{shares:?}");
        assert!((80.0..86.0).contains(&(shares[1] * 100.0)), "{shares:?}");
        assert!((14.0..17.0).contains(&(shares[2] * 100.0)), "{shares:?}");
        assert!(shares[3] * 100.0 < 1.0);

        let km: Vec<f64> = profile
            .layers
            .iter()
            .map(|l| l.thickness_km(6_371.0))
            .collect();
        assert!((km[0] - 20.0).abs() < 0.01);
        assert!((km[1] - 2_871.0).abs() < 0.01);
        assert!((km[2] - 2_260.0).abs() < 0.01);
        assert!((km[3] - 1_220.0).abs() < 0.01);
    }

    #[test]
    fn the_diameter_slider_puts_earth_at_its_centre() {
        let centre = (MIN_DIAMETER_KM * MAX_DIAMETER_KM).sqrt();
        assert!((centre - EARTH_DIAMETER_KM).abs() / EARTH_DIAMETER_KM < 0.01);
    }

    #[test]
    fn custom_thicknesses_are_normalized_and_ordered() {
        let settings = PlanetSettings {
            advanced_layers: true,
            layer_fractions: vec![0.05, 0.45, 0.30, 0.20],
            ..PlanetSettings::earth_default()
        };
        let profile = settings.profile().unwrap();
        assert_eq!(profile.layer_at(0.98).id, LayerId::Crust);
        assert_eq!(profile.layer_at(0.70).id, LayerId::Mantle);
        assert_eq!(profile.layer_at(0.30).id, LayerId::OuterCore);
        assert_eq!(profile.layer_at(0.10).id, LayerId::InnerCore);
        assert!(profile.validate());
    }

    #[test]
    fn mars_and_the_moon_have_their_own_layer_counts() {
        for kind in [PlanetKind::MarsLike, PlanetKind::MoonLike] {
            let profile = LayerProfile::for_kind(kind);
            assert_eq!(profile.layers.len(), 3);
            assert!(profile.validate());
            assert!(
                (profile.layers.iter().map(|l| l.volume_share()).sum::<f64>() - 1.0).abs() < 1e-9
            );
        }
    }

    #[test]
    fn settings_round_trip_through_the_save_format() {
        let settings = PlanetSettings {
            advanced_layers: true,
            layer_fractions: vec![0.05, 0.45, 0.30, 0.20],
            seed: 42,
            ..PlanetSettings::earth_default()
        };
        let decoded = PlanetSettings::decode(&settings.encode()).unwrap();
        assert_eq!(decoded.kind, settings.kind);
        assert!((decoded.diameter_km - settings.diameter_km).abs() < 1e-6);
        assert!(decoded.advanced_layers);
        assert_eq!(decoded.seed, 42);
        assert_eq!(decoded.layer_fractions.len(), 4);
        assert!((decoded.layer_fractions[1] - 0.45).abs() < 1e-9);
    }

    #[test]
    fn sliders_are_reversible_and_layer_edits_stay_normalized() {
        let mut settings = PlanetSettings::earth_default();
        for position in [0.0, 0.25, 0.5, 1.0] {
            settings.set_diameter_slider(position);
            assert!((settings.diameter_slider() - position).abs() < 1e-6);
        }
        settings.set_layer_slider(0, 0.8);
        assert!(settings.advanced_layers);
        let sum: f64 = settings.layer_fractions.iter().sum();
        assert!((sum - 1.0).abs() < 1e-9);
        assert!(settings.validate().is_ok());
    }

    #[test]
    fn a_broken_settings_file_is_refused() {
        assert_eq!(
            PlanetSettings::decode("kind = earth\ndiameter_km = nope\n"),
            Err(SettingsError::BadFormat)
        );
    }

    #[test]
    fn a_bad_diameter_or_layer_count_is_refused() {
        let mut s = PlanetSettings::earth_default();
        s.diameter_km = 10.0;
        assert_eq!(s.validate(), Err(SettingsError::BadDiameter));
        s.diameter_km = EARTH_DIAMETER_KM;
        s.advanced_layers = true;
        s.layer_fractions.pop();
        assert_eq!(s.validate(), Err(SettingsError::LayerCount));
    }
}
